-- RoF2 fellowship: fellowship_campsite_catalogue (custom schema v273)
-- Twin of ManifestEntry .version = 273 in common/database/database_update_manifest_custom.cpp

-- Matching RoF2 descriptions; stable IDs are server policy, not recovered Live IDs.
-- Melee tier values use ordinal1..8 policy with shipped7354..7358 formulas; not recovered Live recipe levels.
-- Lifetime3600 is official 2007 behavior. Radius100 and deterministic maximum focus are emulator policies.
CREATE TABLE IF NOT EXISTS fellowship_campsite_catalogue (
 id INT UNSIGNED PRIMARY KEY, description_id INT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL,
 kit_item_id INT UNSIGNED NOT NULL, lumber_item_id INT UNSIGNED NOT NULL, effect VARCHAR(48) NOT NULL,
 amount INT NOT NULL, spell_level_max INT UNSIGNED NOT NULL, appearance_template_spell_id INT UNSIGNED NOT NULL,
 implemented TINYINT UNSIGNED NOT NULL, source VARCHAR(80) NOT NULL
 ) ENGINE=InnoDB;
